def _walk_vdi_chain(session, vdi_uuid):
    """Yield vdi_recs for each element in a VDI chain"""
    while True:
        vdi_ref = session.call_xenapi("VDI.get_by_uuid", vdi_uuid)
        vdi_rec = session.call_xenapi("VDI.get_record", vdi_ref)
        yield vdi_rec

        parent_uuid = _get_vhd_parent(session, vdi_rec)
        if parent_uuid:
            vdi_uuid = parent_uuid
        else:
            break


def _get_vhd_parent(session, vdi_rec):
    """Retrieve the parent UUID from the VDI record"""
    return vdi_rec['sm_config'].get('vhd-parent')
